const $=id=>document.getElementById(id);
function esc(s){if(!s)return'';return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');}
function ts(){return new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'});}
function ago(t){if(!t)return'';const d=Date.now()-t,m=Math.floor(d/60000),h=Math.floor(m/60),dy=Math.floor(h/24);if(d<60000)return'now';if(m<60)return m+'m';if(h<24)return h+'h';if(dy<7)return dy+'d';return new Date(t).toLocaleDateString([],{month:'short',day:'numeric'});}
function avUrl(n,c='00A884'){return`https://ui-avatars.com/api/?background=${c}&color=fff&bold=true&size=128&name=${encodeURIComponent(n||'U')}`;}
function toast(msg,type='info'){
  document.querySelectorAll('.toast').forEach(e=>e.remove());
  const el=document.createElement('div');el.className='toast';
  el.style.background=type==='error'?'#ef4444':type==='success'?'#00A884':type==='warn'?'#f59e0b':'#2A3942';
  el.textContent=msg;document.body.appendChild(el);
  setTimeout(()=>{el.style.opacity='0';el.style.transition='opacity .3s';setTimeout(()=>el.remove(),300);},3200);
}
