function autoResize(el){el.style.height='auto';el.style.height=Math.min(el.scrollHeight,100)+'px';}
function detectLinks(t){if(!t)return'';return t.replace(/(https?:\/\/[^\s<>"]+)|([^]+?(?=https?:\/\/|$))/g,(m,url,txt)=>{if(url)return`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer" style="color:var(--blue);text-decoration:underline;">${esc(url)}</a>`;return esc(txt);});}
function highlightText(t,q){if(!q||!t)return esc(t);const re=new RegExp(`(${q.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')})`,'gi');return esc(t).replace(re,'<mark>$1</mark>');}

