// ══ SERVICE WORKER ════════════════════════════════════════════════
if('serviceWorker' in navigator){
  const sw=`const CACHE='mkj-v7';
self.addEventListener('install',e=>{e.waitUntil(caches.open(CACHE).then(c=>c.addAll([])));self.skipWaiting();});
self.addEventListener('activate',e=>{e.waitUntil(clients.claim());});
self.addEventListener('fetch',e=>{e.respondWith(fetch(e.request).catch(()=>caches.match(e.request)));});
self.addEventListener('push',e=>{
  const d=e.data?e.data.json():{title:'MKJ Chat',body:'You have a new message'};
  const opts={body:(d.body||'You have a new message').substring(0,120),icon:d.icon||'/icon.png',badge:d.icon||'/icon.png',tag:d.tag||'mkj-msg',vibrate:[200,100,200,100,200],renotify:true,requireInteraction:false,data:{url:d.url||'/'}};
  e.waitUntil(self.registration.showNotification(d.title||'MKJ Chat',opts));
});
self.addEventListener('notificationclick',e=>{
  e.notification.close();
  e.waitUntil(clients.matchAll({type:'window',includeUncontrolled:true}).then(cs=>{
    for(const c of cs){if(c.url&&c.focus)return c.focus();}
    if(clients.openWindow)return clients.openWindow(e.notification.data?.url||'/');
  }));
});`;
  const blob=new Blob([sw],{type:'application/javascript'});
  navigator.serviceWorker.register(URL.createObjectURL(blob)).then(reg=>{
    // Listen for push messages from FCM via service worker
    navigator.serviceWorker.addEventListener('message',e=>{if(e.data?.type==='push')playNotifSound();});
  }).catch(()=>{});
}

// ══ FCM ══════════════════════════════════════════════════════════
async function initFCM(){
  if(!('Notification' in window))return;
  try{
    const perm=await Notification.requestPermission();
    if(perm!=='granted')return;
    const msg=firebase.messaging();
    const token=await msg.getToken({vapidKey:VAPID}).catch(()=>null);
    if(token&&me)await db.ref(`users/${me.uid}/fcmToken`).set(token);
    msg.onMessage(p=>{const{title,body}=p.notification||{};playNotifSound();toast(`🔔 ${title||'MKJ'}: ${body||''}`)});
  }catch(e){console.log('FCM fallback');}
}
function sendPush(title,body,icon){
  if(isDND())return;
  if(Notification.permission==='granted'&&document.visibilityState!=='visible'){
    try{new Notification(title,{body:(body||'').substring(0,80),icon:icon||'',tag:'mkj',silent:false});}catch(e){}
  }
  playNotifSound();
}
function playNotifSound(){
  if(isDND())return;
  const s=localStorage.getItem('notif_sound')||'default';
  if(!NOTIF_SOUNDS[s])return;
  try{const a=new Audio(NOTIF_SOUNDS[s]);a.volume=0.5;a.play().catch(()=>{});}catch(e){}
}
function setNotifSound(v){localStorage.setItem('notif_sound',v);toast('Sound updated ✓','success');}

// ══ DND ══════════════════════════════════════════════════════════
function isDND(){
  if(localStorage.getItem('dnd')!=='true')return false;
  const from=localStorage.getItem('dnd_from'),to=localStorage.getItem('dnd_to');
  if(!from||!to)return true;
  const now=new Date(),cur=now.getHours()*60+now.getMinutes();
  const [fh,fm]=from.split(':').map(Number),[th,tm]=to.split(':').map(Number);
  const f=fh*60+fm,t_=th*60+tm;
  return f<=t_?cur>=f&&cur<=t_:cur>=f||cur<=t_;
}
function toggleDND(){
  const on=localStorage.getItem('dnd')==='true';
  localStorage.setItem('dnd',!on);
  $('tog-dnd').classList.toggle('on',!on);
  $('dnd-time-row').classList.toggle('hidden',on);
  $('dnd-sub').textContent=!on?'Active — notifications silenced':'Silence all notifications';
  toast(!on?'Do Not Disturb ON 🌙':'Do Not Disturb OFF','info');
}
function saveDNDTime(){
  localStorage.setItem('dnd_from',$('dnd-from').value);
  localStorage.setItem('dnd_to',$('dnd-to').value);
}

