// ══ IMAGE COMPRESSION ════════════════════════════════════════════
async function compressImage(file,maxW=1080,q=0.82){
  return new Promise(res=>{
    if(!file.type.startsWith('image/')){res(file);return;}
    const img=new Image(),url=URL.createObjectURL(file);
    img.onload=()=>{
      URL.revokeObjectURL(url);let w=img.width,h=img.height;
      if(w>maxW){h=Math.round(h*maxW/w);w=maxW;}
      const c=document.createElement('canvas');c.width=w;c.height=h;
      c.getContext('2d').drawImage(img,0,0,w,h);
      c.toBlob(b=>res(new File([b],file.name.replace(/\.[^.]+$/,'.jpg'),{type:'image/jpeg'})),'image/jpeg',q);
    };img.onerror=()=>{URL.revokeObjectURL(url);res(file);};img.src=url;
  });
}

// ══ MKJ NUMBER — PERMANENT, NEVER REGENERATE ══════════════════════
function genMKJNum(){return`MKJ-${Math.floor(1000+Math.random()*9000)}`;}
async function getUniqueMKJ(){
  let num,exists=true;
  while(exists){
    num=genMKJNum();
    const s=await db.ref('users').orderByChild('mkjNumber').equalTo(num).once('value');
    exists=s.val()!==null;
  }
  return num;
}

