function setChatWallpaper(t){
  const inp=document.createElement('input');inp.type='file';inp.accept='image/*';
  inp.onchange=e=>{
    const f=e.target.files[0];if(!f)return;
    if(f.size>5*1024*1024)return toast('Max 5MB','error');
    const rd=new FileReader();
    rd.onload=ev=>{
      const key=t==='private'?`wp_${chatId}`:t==='group'?`wp_grp_${curGid}`:'wp_global';
      localStorage.setItem(key,ev.target.result);applyWallpaper(t);toast('Wallpaper set ✓','success');
    };rd.readAsDataURL(f);
  };inp.click();
}
function applyWallpaper(t){
  const id=t==='private'?'priv-msgs':t==='group'?'group-msgs':'global-msgs';
  const el=$(id);if(!el)return;
  const key=t==='private'?`wp_${chatId}`:t==='group'?`wp_grp_${curGid}`:'wp_global';
  const wp=localStorage.getItem(key);
  el.style.backgroundImage=wp?`url(${wp})`:'';
  if(wp){el.style.backgroundSize='cover';el.style.backgroundPosition='center';}
}
function clearChatWallpaper(t){
  const key=t==='private'?`wp_${chatId}`:t==='group'?`wp_grp_${curGid}`:'wp_global';
  localStorage.removeItem(key);applyWallpaper(t);toast('Wallpaper cleared','info');
}

