// ══ CHAT LOCK ════════════════════════════════════════════════════
function pinNav(el,nextId){if(el.value.length===1&&nextId)$(nextId)?.focus();}
function getPinSalt(){
  let salt=localStorage.getItem('chat_pin_salt');
  if(!salt){
    salt=Array.from(crypto.getRandomValues(new Uint8Array(16))).map(b=>b.toString(16).padStart(2,'0')).join('');
    localStorage.setItem('chat_pin_salt',salt);
  }
  return salt;
}
async function hashPin(pin,salt){const buf=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(salt+pin));return Array.from(new Uint8Array(buf)).map(b=>b.toString(16).padStart(2,'0')).join('');}
async function savePin(){
  const pin=['sp1','sp2','sp3','sp4'].map(id=>$(id).value).join('');
  if(!/^\d{4}$/.test(pin))return toast('Enter a 4-digit PIN','error');
  const salt=getPinSalt();
  const hashed=await hashPin(pin,salt);
  localStorage.setItem('chat_pin',hashed);
  localStorage.setItem('chat_pin_v3','true');
  localStorage.removeItem('chat_pin_v2');
  ['sp1','sp2','sp3','sp4'].forEach(id=>{if($(id))$(id).value='';});
  closeModal('chat-lock-modal');toast('PIN set ✓','success');
}
function removePin(){
  localStorage.removeItem('chat_pin');
  localStorage.removeItem('chat_pin_v2');
  localStorage.removeItem('chat_pin_v3');
  localStorage.removeItem('chat_pin_salt');
  closeModal('chat-lock-modal');toast('PIN removed','info');
}
function forgotPin(){
  if(!me)return toast('Please log in again to reset your PIN','error');
  if(!confirm('Reset your PIN? You will need to set a new one after unlocking.'))return;
  localStorage.removeItem('chat_pin');
  localStorage.removeItem('chat_pin_v2');
  localStorage.removeItem('chat_pin_v3');
  localStorage.removeItem('chat_pin_salt');
  $('chat-lock-screen').classList.add('hidden');
  toast('PIN removed. Set a new one in Profile → Privacy.','info');
}
async function checkPin(){
  const entered=['lk1','lk2','lk3','lk4'].map(id=>$(id).value).join('');
  const stored=localStorage.getItem('chat_pin');
  if(!stored){$('chat-lock-screen').classList.add('hidden');return;}
  const isV3=localStorage.getItem('chat_pin_v3')==='true';
  const isV2=localStorage.getItem('chat_pin_v2')==='true';
  let match;
  if(isV3){
    match=(await hashPin(entered,getPinSalt()))===stored;
  }else if(isV2){
    // Legacy PINs were hashed with a fixed shared salt — verify the same way, then upgrade below.
    const buf=await crypto.subtle.digest('SHA-256',new TextEncoder().encode('mkjsalt_'+entered));
    const legacyHash=Array.from(new Uint8Array(buf)).map(b=>b.toString(16).padStart(2,'0')).join('');
    match=legacyHash===stored;
  }else{
    match=atob(stored)===entered;
  }
  if(match){
    if(!isV3){
      const salt=getPinSalt();
      const h=await hashPin(entered,salt);
      localStorage.setItem('chat_pin',h);
      localStorage.setItem('chat_pin_v3','true');
      localStorage.removeItem('chat_pin_v2');
    }
    $('chat-lock-screen').classList.add('hidden');
    ['lk1','lk2','lk3','lk4'].forEach(id=>{if($(id))$(id).value='';});
  }else{
    toast('Wrong PIN ❌','error');
    ['lk1','lk2','lk3','lk4'].forEach(id=>{if($(id))$(id).value='';});
    $('lk1')?.focus();
  }
}
function showLockIfNeeded(){if(me&&localStorage.getItem('chat_pin'))$('chat-lock-screen').classList.remove('hidden');}

