// ══ TYPING INDICATOR ══════════════════════════════════════════════
function handleTyping(chatType){
  if(!me)return;
  let ref;
  if(chatType==='global')ref=db.ref(`typing/global/${me.uid}`);
  else if(chatType==='private'&&chatId)ref=db.ref(`typing/private/${chatId}/${me.uid}`);
  else if(chatType==='group'&&curGid)ref=db.ref(`typing/group/${curGid}/${me.uid}`);
  else return;
  ref.set(Date.now());
  clearTimeout(typTimers[chatType]);
  typTimers[chatType]=setTimeout(()=>ref.remove(),2500);
}
function watchTyping(refPath,displayId){
  db.ref(refPath).on('value',snap=>{
    const data=snap.val()||{};const now=Date.now();
    const typers=Object.entries(data).filter(([uid,t])=>uid!==me?.uid&&(now-t)<3000).map(([uid])=>uid);
    const el=$(displayId);if(!el)return;
    if(!typers.length){
      // Restore original text if we replaced it
      if(el.dataset.original!==undefined){el.textContent=el.dataset.original;delete el.dataset.original;}
      return;
    }
    // Save original text before first overwrite
    if(el.dataset.original===undefined)el.dataset.original=el.textContent;
    Promise.all(typers.slice(0,2).map(uid=>db.ref(`users/${uid}/username`).once('value').then(s=>s.val()||'Someone'))).then(names=>{
      el.innerHTML=`${names.join(', ')} <span class="typing-dots"><span></span><span></span><span></span></span>`;
    });
  });
}

