// ══ MESSAGE SCHEDULING ════════════════════════════════════════════
let scheduledMsgs=JSON.parse(localStorage.getItem('sched_msgs')||'[]');
function openScheduler(ct){schedChat=ct||_attachChat;closeModal('attach-modal');openModal('schedule-modal');}
function scheduleMessage(){
  const msg=$('sched-msg').value.trim(),timeStr=$('sched-time').value;
  if(!msg||!timeStr)return toast('Fill message and time','error');
  const sendAt=new Date(timeStr).getTime();
  if(sendAt<=Date.now())return toast('Pick a future time','error');
  // Snapshot full context at schedule time so it survives navigation
  const entry={
    msg,sendAt,
    chatType:schedChat,
    chatId:chatId||null,
    targetUid:chatTarget?.uid||null,
    targetUsername:chatTarget?.username||null,
    groupId:curGid||null,
    groupName:curGData?.name||null
  };
  scheduledMsgs.push(entry);
  localStorage.setItem('sched_msgs',JSON.stringify(scheduledMsgs));
  closeModal('schedule-modal');$('sched-msg').value='';
  const dest=schedChat==='global'?'Community':schedChat==='group'?(curGData?.name||'Group'):(chatTarget?.username||'contact');
  toast(`📅 Scheduled for ${new Date(sendAt).toLocaleString()} → ${dest}!`,'success');
}
function checkSched(){
  const now=Date.now();let changed=false;
  scheduledMsgs=scheduledMsgs.filter(s=>{
    if(s.sendAt<=now&&me){
      const m={uid:me.uid,username:me.username,mkjNumber:me.mkjNumber,photoURL:me.photoURL,text:s.msg,time:ts(),timestamp:Date.now(),type:'text',scheduled:true,lang:getMyPreferredLanguage()};
      if(s.chatType==='global'){
        db.ref('global_chat').push(m);
        toast(`📅 Scheduled message sent to Community`,'success');
      } else if(s.chatType==='private'&&s.chatId){
        db.ref(`private_chats/${s.chatId}`).push(m);
        // Update both conversation indexes
        db.ref(`conversations/${me.uid}/${s.chatId}`).update({lastMessage:s.msg,timestamp:Date.now()});
        if(s.targetUid)db.ref(`conversations/${s.targetUid}/${s.chatId}`).transaction(ex=>{
          const prev=ex||{};
          return{...prev,targetUid:me.uid,targetUsername:me.username,lastMessage:s.msg,timestamp:Date.now(),unread:(prev.unread||0)+1};
        });
        toast(`📅 Scheduled message sent to ${s.targetUsername||'contact'}`,'success');
      } else if(s.chatType==='group'&&s.groupId){
        db.ref(`group_messages/${s.groupId}`).push(m);
        toast(`📅 Scheduled message sent to ${s.groupName||'group'}`,'success');
      } else {
        toast(`📅 Scheduled message could not be sent — chat no longer available`,'warn');
      }
      changed=true;return false;
    }return true;
  });
  if(changed)localStorage.setItem('sched_msgs',JSON.stringify(scheduledMsgs));
}
setInterval(checkSched,30000);

// ══ FORWARD ══════════════════════════════════════════════════════
function openForward(msg){
  fwdMsg=msg;$('fwd-preview').textContent=msg.text||'[media]';openModal('forward-modal');
  const list=$('fwd-list');list.innerHTML='<p style="color:var(--t2);text-align:center;padding:12px;">Loading contacts…</p>';
  db.ref(`conversations/${me.uid}`).once('value').then(snap=>{
    const data=snap.val()||{};list.innerHTML='';
    if(!Object.keys(data).length){list.innerHTML='<p style="color:var(--t2);text-align:center;padding:12px;">No contacts yet</p>';return;}
    Object.entries(data).filter(([,c])=>!c.isGroup).forEach(([cid,c])=>{
      const div=document.createElement('div');div.className='ci';div.style.borderRadius='12px';
      div.innerHTML=`<img src="${esc(c.targetPhoto||avUrl(c.targetUsername))}" style="width:44px;height:44px;border-radius:50%;object-fit:cover;"><div style="flex:1;"><div style="font-weight:600;color:var(--t1);">${esc(c.targetUsername||'Unknown')}</div><div style="font-size:11px;color:var(--blue);">#${esc(c.targetMKJ||'')}</div></div><button onclick="sendFwd('${esc(c.targetUid)}')" style="padding:8px 14px;background:var(--g);border-radius:10px;color:#fff;font-size:13px;font-weight:600;">Send</button>`;
      list.appendChild(div);
    });
  });
}
async function sendFwd(targetUid){
  if(!fwdMsg||!targetUid||!me)return;
  const fCid=[me.uid,targetUid].sort().join('_');
  // Resolve and permanently bake in the ORIGINAL author's language before we overwrite uid below.
  // Forwarding doesn't change the message TEXT, so the language it was written in must travel
  // with it — otherwise (if fwdMsg.lang was ever missing) a later translation would fall back to
  // getUserPreferredLanguage(msg.uid), which after this line is the FORWARDER's uid, not the
  // original author's. That meant a forwarded message's "source language" silently tracked
  // whatever the forwarder's OWN Settings happened to say at the moment someone translated it —
  // changing every time the forwarder changed their own preference, which is exactly the
  // es-ES-then-yo flip-flop seen for the same never-actually-Spanish, never-actually-Yoruba
  // French message.
  const resolvedLang=fwdMsg.lang||await getUserPreferredLanguage(fwdMsg.uid);
  const m={...fwdMsg,uid:me.uid,username:me.username,time:ts(),timestamp:Date.now(),forwarded:true,lang:resolvedLang};
  delete m.replyTo;
  const preview=m.text||'[forwarded media]';
  db.ref(`private_chats/${fCid}`).push(m);
  // Update sender's conversation index
  db.ref(`conversations/${me.uid}/${fCid}`).update({lastMessage:preview,timestamp:Date.now(),unread:0,targetUid});
  // Update recipient's conversation index via transaction to increment unread
  db.ref(`conversations/${targetUid}/${fCid}`).transaction(ex=>{
    const prev=ex||{};
    return{...prev,targetUid:me.uid,targetUsername:me.username,targetMKJ:me.mkjNumber||'',targetPhoto:me.photoURL||'',lastMessage:preview,timestamp:Date.now(),unread:(prev.unread||0)+1};
  });
  closeModal('forward-modal');toast('Forwarded ✓','success');
}

// ══ TRANSLATE (MyMemory-powered, via our own Netlify Function) ══════
// This is the ONE translation engine used app-wide: by the inline "🌐 Translate"
// button under received messages, by the long-press picker's "Translate" action,
// and by the legacy modal entry points below (kept working, now on the real backend).
//
// Backend: netlify/functions/translate.js, which proxies to the MyMemory
// Translation API. Switched off NVIDIA riva-translate-4b-instruct-v2, which
// only covered 36 non-English languages (no Yoruba/Igbo/Hausa/African
// languages at all) and only translated reliably through English as a pivot
// (so e.g. French -> Spanish silently failed even though English -> French
// worked). MyMemory translates any supported pair directly and covers
// African and other low-resource languages that NVIDIA's model never saw
// during training.

// Full list of languages supported by the translate Netlify Function.
// [code, human-readable label] pairs, used to build every language <select>
// in the app (Settings, and the legacy modals).
const TRANSLATE_LANGUAGES=[
  ['en','English'],
  // ── African & Nigerian languages ──
  ['yo','Yoruba'],['ig','Igbo'],['ha','Hausa'],['sw','Swahili'],['zu','Zulu'],
  ['xh','Xhosa'],['am','Amharic'],['so','Somali'],['ak','Twi (Akan)'],['wo','Wolof'],
  ['af','Afrikaans'],['ny','Chichewa'],['sn','Shona'],['st','Sesotho'],['rw','Kinyarwanda'],
  // ── European ──
  ['ar','Arabic'],['bg','Bulgarian'],['zh-CN','Chinese (Simplified)'],
  ['zh-TW','Chinese (Traditional)'],['hr','Croatian'],['cs','Czech'],['da','Danish'],
  ['nl','Dutch'],['et','Estonian'],['fi','Finnish'],['fr','French'],['de','German'],
  ['el','Greek'],['hu','Hungarian'],['ga','Irish'],['it','Italian'],
  ['lv','Latvian'],['lt','Lithuanian'],['mt','Maltese'],['no','Norwegian'],
  ['pl','Polish'],['pt-BR','Portuguese (Brazil)'],['pt-PT','Portuguese (Portugal)'],
  ['ro','Romanian'],['ru','Russian'],['sr','Serbian'],['sk','Slovak'],['sl','Slovenian'],
  ['es-ES','Spanish (Spain)'],['es-US','Spanish (Latin America)'],['sv','Swedish'],
  ['tr','Turkish'],['uk','Ukrainian'],['cy','Welsh'],
  // ── Middle East / South & Central Asia ──
  ['he','Hebrew'],['fa','Persian (Farsi)'],['hi','Hindi'],['bn','Bengali'],
  ['ur','Urdu'],['pa','Punjabi'],['ta','Tamil'],['te','Telugu'],['mr','Marathi'],
  ['gu','Gujarati'],['ne','Nepali'],['si','Sinhala'],
  // ── East & Southeast Asia ──
  ['id','Indonesian'],['ja','Japanese'],['ko','Korean'],['ms','Malay'],
  ['th','Thai'],['tl','Filipino (Tagalog)'],['vi','Vietnamese'],['km','Khmer'],['my','Burmese']
];

// In-memory cache for this browser session only: fastest lookup, cleared on page reload.
// Keyed as "messageId:targetLang" -> translated string. This is layer 1 of the 3-layer cache.
const _translationMemCache={};

// Read the current user's saved translation target language (localStorage = instant, no network).
// Defaults to English if the user has never opened Settings > Translation.
function getMyPreferredLanguage(){
  return localStorage.getItem('preferred_language')||'en';
}

// Save the current user's preferred language: to localStorage (instant local reads) AND to
// Firebase under users/{uid}/preferredLanguage (so it syncs across devices, and so OTHER users'
// clients can look it up as a guess for "what language did this sender write in").
function setMyPreferredLanguage(lang){
  localStorage.setItem('preferred_language',lang);
  if(me?.uid)db.ref(`users/${me.uid}/preferredLanguage`).set(lang).catch(()=>{});
  toast('Translation language updated','success');
}

// Look up any user's preferred language from Firebase (used as the translation "source language"
// guess for messages they sent). Falls back to English if that user never set a preference.
async function getUserPreferredLanguage(uid){
  if(!uid)return 'en';
  try{
    const snap=await db.ref(`users/${uid}/preferredLanguage`).once('value');
    return snap.val()||'en';
  }catch{return 'en';} // offline / permission error -> just assume English rather than failing the whole translation
}

// Check all 3 cache layers, cheapest first, for an existing translation.
// Returns the cached string, or null if this exact message+language has never been translated before.
//
// Cache key/path bumped to a "v2" namespace (both the local key AND the Firebase path below) on
// switching the backend to Gemini. Earlier testing with NVIDIA (no African-language support) and
// MyMemory (inconsistent quality on uncommon pairs) wrote wrong-language results into the old
// "translations/" path — since translations never expired, those bad entries would otherwise be
// served forever to every user, forever, even with a correct backend now in place. The old path
// is simply never read again; it doesn't need to be manually cleared out.
async function getCachedTranslation(messageId,targetLang){
  const cacheKey=`${messageId}:${targetLang}:v2`;
  if(_translationMemCache[cacheKey])return _translationMemCache[cacheKey]; // layer 1: memory (this tab, this session)
  const lsVal=localStorage.getItem(`xlate_${cacheKey}`); // layer 2: localStorage (this device, persists across reloads)
  if(lsVal){_translationMemCache[cacheKey]=lsVal;return lsVal;}
  try{
    // layer 3: Firebase — shared across ALL users, so if anyone has already translated this
    // exact message into this language, nobody else ever has to call the paid/rate-limited API for it again.
    const snap=await db.ref(`translations_v2/${messageId}/${targetLang}`).once('value');
    const fbVal=snap.val();
    if(fbVal){_translationMemCache[cacheKey]=fbVal;localStorage.setItem(`xlate_${cacheKey}`,fbVal);return fbVal;}
  }catch{/* Firebase unreachable or rules block the read — fall through and call the API instead */}
  return null;
}

// Write a freshly-translated string into all 3 cache layers so this exact
// message+language combination never triggers another API call, from anyone.
function cacheTranslation(messageId,targetLang,translatedText){
  const cacheKey=`${messageId}:${targetLang}:v2`;
  _translationMemCache[cacheKey]=translatedText;
  localStorage.setItem(`xlate_${cacheKey}`,translatedText);
  if(db)db.ref(`translations_v2/${messageId}/${targetLang}`).set(translatedText).catch(()=>{}); // best-effort; ok if it fails
}


// Calls our own Netlify Function, which proxies the MyMemory Translation API.
// Confirmed contract: POST {text, sourceLanguage, targetLanguage} -> {translation}.
// (Contract is identical to the old NVIDIA-backed version, so nothing else
// in this file or in chat-messaging.js needs to change.)
async function callTranslateFunction(text,sourceLang,targetLang){
  console.log('[translate] sending request ->',{sourceLang,targetLang}); // kept for DevTools debugging
  const res=await fetch('/.netlify/functions/translate',{
    method:'POST',
    headers:{'Content-Type':'application/json'},
    body:JSON.stringify({text,sourceLanguage:sourceLang,targetLanguage:targetLang})
  });
  const data=await res.json();
  if(!res.ok)throw new Error(data.error||`Translate function returned HTTP ${res.status}`);
  if(!data.translation)throw new Error('Translate function response had no translation field');
  return data.translation;
}

// Main entry point for translating one message. Checks cache first (see point 5/6 of the spec:
// never re-call the API once a message+language has been translated), otherwise uses the sender's
// language as stamped on the message itself (msg.lang, set when THEY sent it, from their own
// preferred-language setting — this avoids needing to read another user's profile out of Firebase,
// which can silently fail under normal security rules and was the root cause of translations only
// working when the sender happened to be on English). Falls back to the old cross-user lookup only
// for messages sent before this fix that don't have msg.lang yet. Throws on failure so callers can
// show "Translation unavailable."
async function translateMessageText(messageId,text,msg,targetLang){
  const cached=await getCachedTranslation(messageId,targetLang);
  if(cached)return cached;
  const sourceLang=msg.lang||await getUserPreferredLanguage(msg.uid); // msg.lang covers all new messages; old messages fall back
  const translated=await callTranslateFunction(text,sourceLang,targetLang);
  cacheTranslation(messageId,targetLang,translated);
  return translated;
}

// Fills every <select class="lang-select"> with the full supported-language list, binds its change
// listener in JS (more reliable across mobile browsers/WebViews than relying on inline onchange alone),
// and loads the user's saved target language into the Settings dropdown. Safe to call more than once —
// called at app boot AND every time the Profile/Settings view opens, so a failure in one unrelated
// boot-time function can never permanently prevent this from initializing.
function initTranslationUI(){
  document.querySelectorAll('select.lang-select').forEach(sel=>{
    // Only rebuild options if empty, so re-calling this doesn't wipe a select mid-interaction.
    if(!sel.options.length){
      sel.innerHTML=TRANSLATE_LANGUAGES.map(([code,label])=>`<option value="${code}">${esc(label)}</option>`).join('');
    }
  });
  const sel=$('translate-lang-setting');
  if(sel){
    sel.value=getMyPreferredLanguage(); // reflect the currently saved choice
    // Bind in JS (in addition to the inline onchange in index.html) so the save fires even in
    // environments where inline event attributes on <select> are unreliable.
    sel.onchange=()=>{
      toast(`Setting saved: ${sel.value}`,'info'); // TEMP DEBUG: confirms the change actually registered
      setMyPreferredLanguage(sel.value);
    };
  }
}

// ══ LEGACY TRANSLATE MODAL (kept working, now backed by the NVIDIA function) ══
// LEGACY, currently unreachable: no button anywhere calls openTranslate() any more (the app
// consolidated to the single toggleInlineTranslation() flow in chat-messaging.js). Kept only
// because the modal markup still exists in index.html. Previously had a real bug worth noting:
// it used the VIEWER's own preferred language as the source language, which is backwards — it
// should be whoever actually wrote the message. Left uncalled, this couldn't affect any user,
// but is corrected here so nothing incorrect remains in the file even dormant.
function openTranslate(text){xlateText=text;$('xlate-orig').textContent=text;$('xlate-result').style.display='none';openModal('translate-modal');}
async function doTranslate(){
  const lang=$('xlate-lang').value,box=$('xlate-result');
  box.textContent='Translating…';box.style.display='block';
  try{
    box.textContent=await callTranslateFunction(xlateText,'en',lang); // no sender context available here — see note above
  }catch{box.textContent='Translation unavailable.';}
}

// ══ REPORT ═══════════════════════════════════════════════════════
function openReport(msg){
  reportMsg=msg;reportReason='';
  $('report-msg-preview').textContent=msg.text||'[media]';
  document.querySelectorAll('.report-reason').forEach(b=>{b.style.borderColor='transparent';b.style.background='var(--s2)';});
  openModal('report-modal');
}
function selectReport(btn,reason){
  reportReason=reason;
  document.querySelectorAll('.report-reason').forEach(b=>{b.style.borderColor='transparent';b.style.background='var(--s2)';});
  btn.style.borderColor='var(--red)';btn.style.background='rgba(239,68,68,.1)';
}
async function submitReport(){
  if(!reportReason)return toast('Select a reason first','error');
  if(!reportMsg||!me)return;
  const params={report_type:reportReason,reporter_name:me.username,reporter_mkj:me.mkjNumber||'',reported_name:reportMsg.username||'Unknown',reported_mkj:reportMsg.mkjNumber||'',message_content:reportMsg.text||'[media]',time:new Date().toLocaleString()};
  await db.ref('reports').push({...params,reporterUid:me.uid,timestamp:Date.now()});
  try{await emailjs.send(EJS_SVC,EJS_TPL,params);}catch(e){console.log('Email fallback');}
  closeModal('report-modal');toast('Report submitted. We\'ll review within 24 hours. ✓','success');
}

