// ══ FAQ ══════════════════════════════════════════════════════════
function buildFAQ(){
  const list=$('faq-list');if(!list||list.children.length)return;// only build once
  FAQ_DATA.forEach(item=>{
    const div=document.createElement('div');div.style.cssText='border-bottom:1px solid var(--s2);padding:14px 0;cursor:pointer;';
    div.innerHTML=`<div style="font-weight:600;color:var(--t1);font-size:14px;display:flex;justify-content:space-between;align-items:center;">${esc(item.q)}<i class="fa-solid fa-chevron-down" style="color:var(--t2);font-size:12px;transition:transform .2s;"></i></div><div style="font-size:13px;color:var(--t2);margin-top:8px;line-height:1.6;display:none;">${esc(item.a)}</div>`;
    div.onclick=()=>{const ans=div.querySelector('div:last-child'),icon=div.querySelector('i');const open=ans.style.display!=='none';ans.style.display=open?'none':'block';icon.style.transform=open?'':'rotate(180deg)';};
    list.appendChild(div);
  });
}

// ══ CLEANUP OLD MESSAGES ══════════════════════════════════════════
function cleanupOld(){
  const cutoff=Date.now()-(30*24*60*60*1000);
  // Global chat cleanup
  db.ref('global_chat').orderByChild('timestamp').endAt(cutoff).limitToFirst(100).once('value',snap=>{
    const u={};snap.forEach(c=>{u[c.key]=null;});
    if(Object.keys(u).length)db.ref('global_chat').update(u);
  });
  // Statuses cleanup (older than 24h)
  if(me){
    const statusCutoff=Date.now()-86400000;
    db.ref(`statuses/${me.uid}`).orderByChild('timestamp').endAt(statusCutoff).once('value',snap=>{
      const u={};snap.forEach(c=>{u[c.key]=null;});
      if(Object.keys(u).length)db.ref(`statuses/${me.uid}`).update(u);
    });
  }
}

// ══ EMOJI KEYBOARD ═══════════════════════════════════════════════
let ekbChat=null;
const EMOJIS=['❤️','🧡','💛','💚','💙','💜','😀','😂','🤣','😊','😍','🥰','😎','🤩','🥳','😢','😭','😡','🤬','😱','😮','🤔','😴','🤗','🫶','👍','👎','👏','🙏','🤝','✌️','👌','💪','🔥','⭐','💯','✅','❌','🎉','🎊','🏆','🚀','💡','🎵','🎮','🍕','💀','👀','😅','🙄','😤','🤯','🥺','😻','🫡','🤌','🥹','🎯','💎','🌈','🌙','⚡'];
function openEmojiKeyboard(chatType){ekbChat=chatType;openModal('emoji-kb-modal');emojiKbTab('emoji');}
function emojiKbTab(tab){
  ['emoji','sticker','gif'].forEach(t=>{
    const panel=$(`ekb-${t}-panel`),btn=$(`ekb-tab-${t}`);
    if(panel)panel.classList.toggle('hidden',t!==tab);
    if(btn){btn.style.background=t===tab?'var(--g)':'var(--s2)';btn.style.color=t===tab?'#fff':'var(--t2)';}
  });
  if(tab==='emoji'){buildEmojiGrid();}
  else if(tab==='sticker'){buildStickerGrid();}
  else if(tab==='gif'){loadTrendingGifs();}
}
function buildEmojiGrid(){
  const grid=$('emoji-full-grid');if(!grid)return;grid.innerHTML='';
  EMOJIS.forEach(em=>{const btn=document.createElement('button');btn.textContent=em;btn.style.cssText='font-size:24px;padding:4px;border-radius:8px;';btn.onclick=()=>{insertEmoji(em);};grid.appendChild(btn);});
}
function insertEmoji(em){
  const inpId=ekbChat==='global'?'g-inp':ekbChat==='private'?'p-inp':'grp-inp';
  const inp=$(inpId);if(inp){inp.value+=em;inp.focus();autoResize(inp);}
}
